def build() -> list[dict]:
    rows = []
    for index, (app, lang, text, marks) in enumerate(CASES, start=1):
        spans = []
        cursor = 0
        for mark in marks:
            kind, value = ("PERSON", mark)
            if ":" in mark and mark.split(":", 1)[0].isupper():
                kind, value = mark.split(":", 1)
            start = text.find(value, cursor if kind == "PERSON" else 0)
            if start < 0:
                start = text.find(value)
            if start < 0:
                raise ValueError(f"case {index}: {value!r} not in {text!r}")
            spans.append({"start": start, "end": start + len(value), "kind": kind, "text": value})
            cursor = start + len(value)
        rows.append({"id": index, "app": app, "lang": lang, "text": text, "spans": spans})
    return rows


if __name__ == "__main__":
    out = Path(__file__).with_name("redaction_eval.jsonl")
    rows = build()
    out.write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rows), encoding="utf-8")
    names = sum(1 for r in rows for s in r["spans"] if s["kind"] == "PERSON")
    print(f"{len(rows)} cases, {names} labeled names -> {out}")
